    const servicesWrap=root.querySelector('[data-request-services-list]'),serviceCount=root.querySelector('[data-request-service-count]'),servicesTotal=root.querySelector('[data-request-services-total]'),servicesStatus=root.querySelector('[data-request-services-status]');
    const vehicleIdEl=form.querySelector('[data-request-vehicle-id]'),vehicleTitleEl=form.querySelector('[data-request-car-title]'),vehicleLabel=root.querySelector('[data-request-vehicle-label]'),vehicleMeta=root.querySelector('[data-request-vehicle-meta]');
    const offerModeEl=form.querySelector('[data-request-offer-mode]'),cityEl=form.querySelector('[data-request-city]'),latEl=form.querySelector('[data-request-lat]'),lngEl=form.querySelector('[data-request-lng]'),visitModeEl=form.querySelector('[data-request-visit-mode]'),dateEl=form.querySelector('[data-booking-date]'),timeEl=form.querySelector('[data-booking-time]');
    const budgetEl=form.querySelector('[data-request-budget]'),budgetModeEl=form.querySelector('[data-request-budget-mode]'),directMasterIdEl=form.querySelector('[data-request-direct-master-id]'),directMasterNameEl=form.querySelector('[data-request-direct-master-name]');
    const addressEl=form.querySelector('[data-request-address]'),addressWrap=root.querySelector('[data-request-address-wrap]'),problemModeEl=form.querySelector('[data-request-problem-mode]');
    const mediaInput=form.querySelector('[data-request-media]'),mediaPreview=root.querySelector('[data-request-media-preview]'),mediaLimit=root.querySelector('[data-request-media-limit]');
    const REQUEST_DRAFT_KEY='kareta.request.draft.kflow';
    const LEGACY_DRAFT_KEY='kareta.request.draft.v3';
    const LEGACY_SERVICE_DRAFT_KEY='kareta.request.services';
    let prefill=null,draft={},step=0,catalog=[],offers=[],vehicles=[],selectedVehicle=null,servicesReady=false,primaryId='',pickerMode='',createdOrder=null,mastersCatalog=[],customServices=[],submitting=false;
    let mediaFiles=[];
    const mediaUrls=[];
    const selectedIds=new Set();
    try{prefill=JSON.parse(sessionStorage.getItem('kareta.request.prefill')||'null');}catch(_e){prefill=null;}
    try{draft=JSON.parse(sessionStorage.getItem(REQUEST_DRAFT_KEY)||sessionStorage.getItem(LEGACY_DRAFT_KEY)||'{}')||{};}catch(_e){draft={};}
    customServices=(Array.isArray(draft.customServices)?draft.customServices:[]).map(row=>({id:text(row?.id)||`custom:${Date.now()}:${Math.random().toString(36).slice(2,7)}`,name:text(row?.name),category:'По описанию',price:Math.max(0,Number(row?.price||0)),custom:true})).filter(row=>row.name);
