    if(Number(draft.flowVersion||0)!==REQUEST_FLOW_VERSION){const previousVersion=Number(draft.flowVersion||0),legacyStep=Math.max(0,Number(draft.step||0));if(previousVersion===8)draft.step=legacyStep;else if(previousVersion===7)draft.step=[0,3,3,1,2,4][Math.min(5,legacyStep)]??0;else draft.step=0;draft.flowVersion=REQUEST_FLOW_VERSION;}
